(function () {
  var D = window.ECO_ROADMAP;
  var root = document.getElementById("tab-root");
  var taskIndex = 0;

  function esc(s) {
    if (!s) return "";
    return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }

  function actBadge(act) {
    var map = {
      new: ["act-new", "MỚI"],
      keep: ["act-keep", "GIỮ"],
      del: ["act-del", "XÓA"],
      merge: ["act-merge", "GỘP"],
      move: ["act-move", "CHUYỂN"],
      edit: ["act-edit", "SỬA"],
      later: ["act-later", "SAU"]
    };
    var m = map[act] || ["act-later", act || "?"];
    return '<span class="badge-act ' + m[0] + '">' + m[1] + "</span>";
  }

  function priBadge(pri) {
    var cls = pri === "P0" ? "danger" : pri === "P1" ? "warning text-dark" : pri === "P2" ? "info text-dark" : "secondary";
    return '<span class="badge bg-' + cls + '">' + esc(pri) + "</span>";
  }

  function taskRow(task, prefix) {
    var id = prefix + "-" + (taskIndex++);
    var files = (task.files || []).map(function (f) {
      return '<div class="file-path">' + esc(f) + "</div>";
    }).join("");
    var note = task.note ? '<div class="text-muted small mt-1"><i class="bi bi-info-circle"></i> ' + esc(task.note) + "</div>" : "";
    return (
      '<div class="file-row task-item" data-search="' + esc((task.t + " " + (task.files || []).join(" ")).toLowerCase()) + '">' +
      '<input type="checkbox" class="form-check-input task-cb mt-1" data-id="' + id + '">' +
      '<div><div class="d-flex flex-wrap align-items-center gap-1">' + actBadge(task.act) + "<strong>" + esc(task.t) + "</strong></div>" +
      files + note + "</div></div>"
    );
  }

  function renderPhaseCard(phase, prefix, colorClass) {
    var tasks = (phase.tasks || []).map(function (t) { return taskRow(t, prefix); }).join("");
    return (
      '<div class="card-phase open" data-search="' + esc((phase.title + " " + phase.id).toLowerCase()) + '">' +
      '<div class="ph-head" onclick="this.parentElement.classList.toggle(\'open\')">' +
      '<span class="badge rounded-pill" style="background:' + (colorClass || "#6c757d") + '">' + esc(phase.id) + "</span>" +
      "<div class='flex-grow-1'><strong>" + esc(phase.title) + "</strong>" +
      '<div class="small text-muted">' + esc(phase.weeks) + " · " + (phase.tasks || []).length + " task</div></div>" +
      priBadge(phase.pri) +
      '<i class="bi bi-chevron-down ms-2"></i></div>' +
      '<div class="ph-body">' + tasks + "</div></div>"
    );
  }

  function renderPhases(key, titleClass, color) {
    return (D.phases[key] || []).map(function (p) {
      return renderPhaseCard(p, key, color);
    }).join("");
  }

  function renderFileOpTable(items, showWhen) {
    return (items || []).map(function (it, i) {
      var when = showWhen && it.when ? '<td class="small">' + esc(it.when) + "</td>" : "";
      var flow = it.flow ? '<span class="badge bg-secondary">' + esc(it.flow) + "</span>" : "";
      return (
        "<tr data-search='" + esc((it.path + " " + (it.reason || "") + " " + (it.from || "") + " " + (it.to || "")).toLowerCase()) + "'>" +
        "<td>" + actBadge(it.act || "edit") + flow + "</td>" +
        "<td><code class='small'>" + esc(it.path || it.from) + "</code>" +
        (it.to ? "<br><i class='bi bi-arrow-right text-muted'></i> <code class='small'>" + esc(it.to) + "</code>" : "") +
        "</td>" +
        "<td class='small'>" + esc(it.reason) + "</td>" +
        when + "</tr>"
      );
    }).join("");
  }

  function renderMergeBlocks() {
    return (D.fileOps.merge || []).map(function (m) {
      var pairs = (m.pairs || []).map(function (p) {
        return "<li class='small'><code>" + esc(p[0]) + "</code> + <code>" + esc(p[1]) + "</code></li>";
      }).join("");
      return (
        '<div class="card mb-3" data-search="' + esc((m.from + m.to).toLowerCase()) + '">' +
        '<div class="card-header d-flex justify-content-between">' + actBadge("merge") +
        "<strong>Gộp folder</strong> " + priBadge("P1") + "</div>" +
        '<div class="card-body small">' +
        "<p><code>" + esc(m.from) + "</code> → <code>" + esc(m.to) + "</code></p>" +
        "<p>" + esc(m.reason) + " · <em>" + esc(m.when) + "</em></p>" +
        (pairs ? "<ul class='mb-0'>" + pairs + "</ul>" : "") +
        "</div></div>"
      );
    }).join("");
  }

  function renderPageInventory(rows, title) {
    var tr = (rows || []).map(function (r) {
      return (
        "<tr data-search='" + esc((r.page + r.url + r.control).toLowerCase()) + "'>" +
        "<td><code>" + esc(r.page) + "</code></td>" +
        "<td class='small'>" + esc(r.url) + "</td>" +
        "<td class='small'><code>" + esc(r.control) + "</code></td>" +
        "<td><span class='badge bg-secondary'>" + esc(r.phase) + "</span></td>" +
        "<td class='small'>" + esc(r.master) + "</td></tr>"
      );
    }).join("");
    return (
      '<div class="table-responsive"><table class="table table-sm table-hover compare-table">' +
      "<thead><tr><th>" + title + "</th><th>URL</th><th>Control</th><th>Phase</th><th>Master mới</th></tr></thead>" +
      "<tbody>" + tr + "</tbody></table></div>"
    );
  }

  /* ── BUILD TABS ── */
  var html = "";

  // OVERVIEW
  html += '<div class="tab-pane-custom active" id="tab-overview">';
  html += '<h1 class="h4 mb-3">Tổng quan chiến lược migrate</h1>';
  html += '<div class="alert alert-conflict alert-conflict p-3 mb-3"><strong><i class="bi bi-exclamation-octagon"></i> Xung đột hiện tại:</strong> BS3 (<code>Theme/</code>) + BS4 (<code>ELibPC_Files/</code>) + jQuery 1.12/3.5 load cùng lúc trên Master. <strong>Bắt buộc tạo Master mới (BS5 only) trước khi sửa từng trang.</strong></div>';
  html += '<div class="row g-2 mb-4">';
  html += '<div class="col-6 col-md-3"><div class="stat-mini"><div class="n text-primary">' + D.stats.pages + '</div><small class="text-muted">ASPX</small></div></div>';
  html += '<div class="col-6 col-md-3"><div class="stat-mini"><div class="n" style="color:var(--lib)">' + D.stats.elibPages + '</div><small class="text-muted">Trang Thư viện</small></div></div>';
  html += '<div class="col-6 col-md-3"><div class="stat-mini"><div class="n text-primary">' + D.stats.elControls + '</div><small class="text-muted">Controls Lib (EL)</small></div></div>';
  html += '<div class="col-6 col-md-3"><div class="stat-mini"><div class="n" style="color:var(--lib)">' + D.stats.libControls + '</div><small class="text-muted">Controls ELib</small></div></div>';
  html += "</div>";

  html += '<div class="row g-3">';
  html += '<div class="col-lg-6"><div class="card h-100 border-primary"><div class="card-header bg-primary text-white"><i class="bi bi-mortarboard"></i> Luồng E-Learning</div><div class="card-body small">';
  html += "<ol class='mb-0'><li><strong>E0–E1</strong> Header + Search + Detail (tuần 8–9)</li><li><strong>E2</strong> Lesson/Topic CRUD — LessonEdit khó nhất (10–12)</li><li><strong>E3</strong> Báo cáo ViewLog, MeetLog (13–14)</li><li><strong>E4–E5</strong> SIMS, Popup, retire BDS (15–18)</li></ol>";
  html += "<p class='mt-2 mb-0 text-muted'>Master: <code>BDS.Master</code> → <code>Masters/ELearning.Master</code></p></div></div></div>";
  html += '<div class="col-lg-6"><div class="card h-100" style="border-color:var(--lib)"><div class="card-header text-white" style="background:var(--lib)"><i class="bi bi-book"></i> Luồng Thư viện — <strong>PILOT TRƯỚC</strong></div><div class="card-body small">';
  html += "<ol class='mb-0'><li><strong>L0</strong> ELibV2.Master + gộp CSS (tuần 3)</li><li><strong>L1</strong> Home → Viewer — 6 trang public (3–4)</li><li><strong>L2–L3</strong> Mượn trả + Báo cáo (5–6)</li><li><strong>L4–L5</strong> Gộp ELib+ELibPage → LibUI, xóa ELibPC (6–7)</li></ol>";
  html += "<p class='mt-2 mb-0 text-muted'>Master: <code>ELib.Master</code> → <code>Masters/ELibV2.Master</code></p></div></div></div>";
  html += "</div>";

  html += '<div class="section-title shared mt-4">Nguyên tắc migrate</div><ul class="small">';
  html += "<li><strong>1 trang = 1 PR</strong> — chỉ đổi markup .ascx, giữ code-behind C#</li>";
  html += "<li><strong>Master song song</strong> — không ghi đè BDS/ELib cũ cho đến L5/E5</li>";
  html += "<li><strong>Logic IsElib/IsSTV</strong> giữ — chỉ tách UI/menu</li>";
  html += "<li><strong>Folder mới Controls/LibUI/</strong> cho Thư viện — tránh nhầm Controls/Lib/ (E-Learning)</li>";
  html += "</ul></div>";

  // SHARED
  html += '<div class="tab-pane-custom" id="tab-shared">';
  html += '<h1 class="h4 mb-1">Nền tảng chung (Shared)</h1><p class="text-muted small mb-3">Làm trước cả 2 luồng · Phase S0 → S2</p>';
  html += renderPhases("shared", "shared", "#6c757d");
  html += '<div class="section-title shared">Cấu trúc thư mục mới</div>';
  html += '<pre class="small bg-body-secondary p-3 rounded">Assets/v2/\n  vendor/ bootstrap-5.3.3, bootstrap-icons, jquery-3.7.1, datatables, sweetalert2\n  css/ eco-tokens.css, eco-components.css, eco-el.css, eco-lib.css, eco-dark.css, legacy-bridge.css\n  js/  eco-theme.js, eco-alert.js, eco-el.js, eco-lib.js\nMasters/\n  ELearning.Master, ELibV2.Master, Auth.Master, PopupV2.Master\nControls/\n  Shared/ PageShell.ascx, HeaderBase.ascx\n  EL/       Header, Footer (E-Learning)\n  LibUI/    Header, Footer, MainMenu (Thư viện — tên mới tránh Lib/)</pre>';
  html += "</div>";

  // LIB
  html += '<div class="tab-pane-custom" id="tab-lib">';
  html += '<h1 class="h4 mb-1"><span style="color:var(--lib)">Luồng Thư viện điện tử</span></h1>';
  html += '<p class="text-muted small mb-3">13 trang · 38 controls · Pilot tuần 3 — <strong>bắt đầu từ Home.aspx</strong></p>';
  html += renderPhases("lib", "lib", "var(--lib)");
  html += '<div class="section-title lib">Inventory trang ELib</div>';
  html += renderPageInventory(D.elibPages, "Pages/ELib/");
  html += '<div class="section-title lib mt-3">Controls cần gộp (ELib + ELibPage → LibUI)</div>';
  html += '<table class="table table-sm compare-table"><thead><tr><th>ELibPage (page shell)</th><th>ELib (logic)</th><th>→ LibUI (đích)</th></tr></thead><tbody>';
  html += "<tr><td>Home.ascx</td><td>HomeBody + HomeTop</td><td>LibUI/Home.ascx</td></tr>";
  html += "<tr><td>BookSearch.ascx</td><td>BookSearch.ascx</td><td>LibUI/BookSearch.ascx</td></tr>";
  html += "<tr><td>BookList.ascx</td><td>BookList + BookThumb</td><td>LibUI/BookList.ascx</td></tr>";
  html += "<tr><td>Cate.ascx</td><td>CateBlock + CateSideBar</td><td>LibUI/Cate.ascx</td></tr>";
  html += "<tr><td>BorrowBook/*</td><td>BookBorrow/*</td><td>LibUI/Borrow/*</td></tr>";
  html += "<tr><td>Report/*</td><td>—</td><td>LibUI/Report/*</td></tr>";
  html += "</tbody></table></div>";

  // EL
  html += '<div class="tab-pane-custom" id="tab-el">';
  html += '<h1 class="h4 mb-1"><span class="text-primary">Luồng E-Learning</span></h1>';
  html += '<p class="text-muted small mb-3">33+ trang Lib · 69 controls · Sau khi Thư viện xong · Phase E0 → E5</p>';
  html += renderPhases("el", "el", "var(--el)");
  html += '<div class="section-title el">Inventory trang chính (ưu tiên)</div>';
  html += renderPageInventory(D.elPages, "Pages/Lib/");
  html += '<div class="section-title el mt-3">Nhóm controls theo folder</div>';
  html += '<div class="row g-2 small">';
  var elFolders = [
    ["Lesson/", "5", "E2", "LessonEdit = khó nhất"],
    ["Topic/", "7", "E2", ""],
    ["ManagerBook/", "9", "E2", ""],
    ["BookCategory/", "9", "E2", ""],
    ["ViewLog/", "4", "E3", "Chart.js"],
    ["MeetLog/", "5", "E3", ""],
    ["Tag/", "3", "E2", ""],
    ["WorkPlan/", "3", "E4", "Ưu tiên thấp"],
    ["ManagerLessonPlan/", "5", "E4", "Ưu tiên thấp"]
  ];
  elFolders.forEach(function (f) {
    html += '<div class="col-md-4"><div class="border rounded p-2"><code>Controls/Lib/' + f[0] + "</code><br>" + f[1] + " controls · " + f[2];
    if (f[3]) html += " · <em>" + f[3] + "</em>";
    html += "</div></div>";
  });
  html += "</div></div>";

  // FILES
  html += '<div class="tab-pane-custom" id="tab-files">';
  html += '<h1 class="h4 mb-3">Xóa · Thêm · Gộp · Giữ</h1>';
  html += '<div class="filter-bar no-print"><div class="btn-group btn-group-sm" role="group" id="fileFilter">';
  html += '<button type="button" class="btn btn-outline-secondary active" data-f="all">Tất cả</button>';
  html += '<button type="button" class="btn btn-outline-danger" data-f="del">Xóa</button>';
  html += '<button type="button" class="btn btn-outline-success" data-f="add">Thêm</button>';
  html += '<button type="button" class="btn btn-outline-warning" data-f="merge">Gộp</button>';
  html += '<button type="button" class="btn btn-outline-info" data-f="keep">Giữ</button>';
  html += "</div></div>";

  html += '<div id="sec-del"><div class="section-title text-danger"><i class="bi bi-trash"></i> XÓA (sau khi migrate xong phase tương ứng)</div>';
  html += '<div class="table-responsive"><table class="table table-sm compare-table"><thead><tr><th></th><th>Đường dẫn</th><th>Lý do</th><th>Khi nào</th></tr></thead><tbody>';
  D.fileOps.delete.forEach(function (it) { it.act = "del"; });
  html += renderFileOpTable(D.fileOps.delete, true) + "</tbody></table></div></div>";

  html += '<div id="sec-add"><div class="section-title text-success"><i class="bi bi-plus-circle"></i> THÊM MỚI</div>';
  html += '<div class="table-responsive"><table class="table table-sm compare-table"><thead><tr><th></th><th>Đường dẫn</th><th>Mục đích</th><th>Phase</th></tr></thead><tbody>';
  D.fileOps.add.forEach(function (it) { it.act = "new"; });
  html += renderFileOpTable(D.fileOps.add, true) + "</tbody></table></div></div>";

  html += '<div id="sec-merge"><div class="section-title" style="color:#fd7e14"><i class="bi bi-intersect"></i> GỘP / TÁI CẤU TRÚC</div>';
  html += renderMergeBlocks() + "</div>";

  html += '<div id="sec-keep"><div class="section-title text-info"><i class="bi bi-shield-check"></i> GIỮ TẠM (không xóa sớm)</div>';
  html += '<div class="table-responsive"><table class="table table-sm compare-table"><thead><tr><th></th><th>File</th><th>Lý do giữ</th><th>Luồng</th></tr></thead><tbody>';
  D.fileOps.keep.forEach(function (it) { it.act = "keep"; });
  html += renderFileOpTable(D.fileOps.keep, false) + "</tbody></table></div></div>";

  html += '<div class="card mt-3 border-secondary"><div class="card-header"><strong>So sánh Master hiện tại vs mới</strong></div><div class="card-body p-0">';
  html += '<table class="table table-sm compare-table mb-0"><thead><tr><th>Hiện tại</th><th>CSS/JS load</th><th>Master mới</th><th>CSS/JS load</th></tr></thead><tbody>';
  html += "<tr><td><code>BDS.Master</code></td><td class='small'>Theme BS3, jQuery 1.12, style.css, App_Themes</td><td><code>ELearning.Master</code></td><td class='small'>Assets/v2 BS5 only, eco-el.css, jQuery 3.7</td></tr>";
  html += "<tr><td><code>ELib.Master</code></td><td class='small'>Theme BS3 + ELibPC BS4 (xung đột!)</td><td><code>ELibV2.Master</code></td><td class='small'>Assets/v2 BS5 only, eco-lib.css</td></tr>";
  html += "<tr><td><code>HomeMaster.Master</code></td><td class='small'>Portal home</td><td><code>ELearning.Master</code></td><td class='small'>Gộp vào EL</td></tr>";
  html += "<tr><td><code>Popup.Master</code></td><td class='small'>Editor popup</td><td><code>PopupV2.Master</code></td><td class='small'>BS5 minimal, không header</td></tr>";
  html += "</tbody></table></div></div></div>";

  // TIMELINE
  html += '<div class="tab-pane-custom" id="tab-timeline">';
  html += '<h1 class="h4 mb-3">Timeline 18 tuần</h1><div class="row"><div class="col-lg-8">';
  D.timeline.forEach(function (t) {
    html += '<div class="card mb-3" style="border-left:4px solid ' + t.color + '"><div class="card-body">';
    html += '<div class="d-flex justify-content-between"><strong>Tuần ' + esc(t.w) + "</strong><span class='badge' style='background:" + t.color + "'>" + esc(t.label) + "</span></div>";
    html += '<div class="tl-bar"><div class="tl-fill" style="width:100%;background:' + t.color + '"></div></div>';
    html += "<ul class='small mb-0'>" + t.items.map(function (i) { return "<li>" + esc(i) + "</li>"; }).join("") + "</ul></div></div>";
  });
  html += '</div><div class="col-lg-4"><div class="card"><div class="card-header">Thứ tự ưu tiên</div><div class="card-body small">';
  html += "<p><span class='badge bg-danger'>P0</span> Foundation + Auth + ELib Home</p>";
  html += "<p><span class='badge bg-warning text-dark'>P1</span> ELib full + EL Search/Detail</p>";
  html += "<p><span class='badge bg-info text-dark'>P2</span> Báo cáo cả 2 luồng</p>";
  html += "<p><span class='badge bg-secondary'>P3</span> LessonEdit, SIMS, cleanup</p>";
  html += "<hr><p class='mb-0'><strong>Checklist mỗi trang:</strong><br>Desktop · Tablet · Mobile · Light · Dark · PostBack · Quyền user</p>";
  html += "</div></div></div></div></div>";

  // STACK
  html += '<div class="tab-pane-custom" id="tab-stack">';
  html += '<h1 class="h4 mb-3">Thư viện JS/CSS</h1>';
  html += '<table class="table table-sm compare-table"><thead><tr><th>Thư viện</th><th>Version</th><th>Thay thế</th><th>Phase</th><th>Luồng</th></tr></thead><tbody>';
  D.stack.forEach(function (s) {
    html += "<tr><td><strong>" + esc(s.name) + "</strong></td><td>" + esc(s.ver) + "</td><td class='small'>" + esc(s.replaces) + "</td><td>" + priBadge(s.phase) + "</td><td>" + esc(s.flow) + "</td></tr>";
  });
  html += "</tbody></table>";
  html += '<div class="section-title shared mt-3">Map class BS3 → BS5 (legacy-bridge.css)</div>';
  html += '<table class="table table-sm"><thead><tr><th>Cũ (BS3/Theme)</th><th>Mới (BS5)</th></tr></thead><tbody>';
  var maps = [["panel panel-default", "card"], ["panel-heading", "card-header"], ["panel-body", "card-body"], ["btn btn-default", "btn btn-secondary"], ["form-group", "mb-3"], ["control-label", "form-label"], ["input-group-addon", "input-group-text"], ["pull-right", "float-end"], ["pull-left", "float-start"], ["hidden-xs", "d-none d-sm-block"], ["col-xs-*", "col-*"]];
  maps.forEach(function (m) { html += "<tr><td><code>" + m[0] + "</code></td><td><code>" + m[1] + "</code></td></tr>"; });
  html += "</tbody></table></div>";

  root.innerHTML = html;

  /* ── NAV ── */
  document.getElementById("sideNav").addEventListener("click", function (e) {
    var link = e.target.closest("[data-tab]");
    if (!link) return;
    e.preventDefault();
    document.querySelectorAll(".nav-side .nav-link").forEach(function (l) { l.classList.remove("active"); });
    link.classList.add("active");
    document.querySelectorAll(".tab-pane-custom").forEach(function (p) { p.classList.remove("active"); });
    document.getElementById("tab-" + link.getAttribute("data-tab")).classList.add("active");
  });

  /* ── SEARCH ── */
  document.getElementById("globalSearch").addEventListener("input", function () {
    var q = this.value.toLowerCase().trim();
    document.querySelectorAll("[data-search]").forEach(function (el) {
      el.style.display = !q || el.getAttribute("data-search").indexOf(q) >= 0 ? "" : "none";
    });
  });

  /* ── EXPAND ── */
  document.getElementById("btnExpand").addEventListener("click", function () {
    var allOpen = document.querySelectorAll(".card-phase.open").length === document.querySelectorAll(".card-phase").length;
    document.querySelectorAll(".card-phase").forEach(function (p) {
      if (allOpen) p.classList.remove("open"); else p.classList.add("open");
    });
  });

  /* ── PROGRESS ── */
  function updateProgress() {
    var all = document.querySelectorAll(".task-cb");
    var done = document.querySelectorAll(".task-cb:checked");
    var pct = all.length ? Math.round((done.length / all.length) * 100) : 0;
    document.getElementById("totalProgress").style.width = pct + "%";
    document.getElementById("progressLabel").textContent = done.length + " / " + all.length + " task (" + pct + "%)";
  }
  document.querySelectorAll(".task-cb").forEach(function (cb, i) {
    var k = "eco-cms-task-" + i;
    if (localStorage.getItem(k) === "1") cb.checked = true;
    cb.addEventListener("change", function () {
      localStorage.setItem(k, cb.checked ? "1" : "0");
      updateProgress();
    });
  });
  updateProgress();

  /* ── THEME ── */
  window.toggleTheme = function () {
    var html = document.documentElement;
    var dark = html.getAttribute("data-bs-theme") === "dark";
    html.setAttribute("data-bs-theme", dark ? "light" : "dark");
    document.getElementById("themeIco").className = dark ? "bi bi-moon-stars" : "bi bi-sun";
    localStorage.setItem("eco-cms-theme", dark ? "light" : "dark");
  };
  if (localStorage.getItem("eco-cms-theme") === "dark") {
    document.documentElement.setAttribute("data-bs-theme", "dark");
    document.getElementById("themeIco").className = "bi bi-sun";
  }
})();

