/* ── NAV ── */
var mermaidReady = false;
var mermaidRendered = false;

function getMermaidTheme() {
  return document.documentElement.getAttribute("data-bs-theme") === "dark" ? "dark" : "default";
}

function initMermaid() {
  if (typeof mermaid === "undefined") return;
  mermaid.initialize({
    startOnLoad: false,
    theme: getMermaidTheme(),
    securityLevel: "loose",
    flowchart: { useMaxWidth: true, htmlLabels: true, curve: "basis" },
    gantt: { useMaxWidth: true }
  });
  mermaidReady = true;
}

function renderMermaidDiagrams(force) {
  if (typeof mermaid === "undefined") return;
  if (!mermaidReady) initMermaid();
  var tab = document.getElementById("tab-diagrams");
  if (!tab || !tab.classList.contains("active")) return;
  if (mermaidRendered && !force) return;

  mermaid.initialize({ theme: getMermaidTheme() });

  document.querySelectorAll("#diagramContainer .mermaid").forEach(function (el) {
    var card = el.closest(".diagram-card");
    if (card && card.style.display === "none") return;
    var src = el.getAttribute("data-src") || el.textContent;
    if (!el.getAttribute("data-src")) el.setAttribute("data-src", src);
    el.removeAttribute("data-processed");
    el.innerHTML = src;
  });

  mermaid.run({ querySelector: "#diagramContainer .mermaid" }).then(function () {
    mermaidRendered = true;
  }).catch(function (err) {
    console.warn("Mermaid render:", err);
  });
}

document.getElementById("sideNav").addEventListener("click", function (e) {
  var link = e.target.closest("[data-tab]");
  if (!link) return;
  e.preventDefault();
  document.querySelectorAll(".nav-side .nav-link").forEach(function (l) { l.classList.remove("active"); });
  link.classList.add("active");
  document.querySelectorAll(".tab-pane-custom").forEach(function (p) { p.classList.remove("active"); });
  document.getElementById("tab-" + link.getAttribute("data-tab")).classList.add("active");
  if (link.getAttribute("data-tab") === "diagrams") {
    setTimeout(function () { renderMermaidDiagrams(false); }, 80);
  }
});

